80	                        + "ORDER BY s.block_no, s.seat_no LIMIT 1",
81	                (rs, n) -> new VacantSeat(rs.getInt(1), rs.getInt(2)),
82	                experimentId);
83	        return seats.isEmpty() ? null : seats.get(0);
84	    }
