1	package com.example.starter.blind.service;
2	
3	import com.example.starter.blind.Actor;
4	import com.example.starter.blind.ApiException;
5	import com.example.starter.blind.Clock;
6	import com.example.starter.blind.repo.IdempotencyRepository;
7	import com.fasterxml.jackson.core.JsonProcessingException;
8	import com.fasterxml.jackson.databind.ObjectMapper;
9	import org.springframework.dao.DuplicateKeyException;
10	import org.springframework.http.HttpHeaders;
11	import org.springframework.http.MediaType;
12	import org.springframework.http.ResponseEntity;
13	import org.springframework.stereotype.Service;
14	import org.springframework.transaction.annotation.Transactional;
15	
16	import java.nio.charset.StandardCharsets;
17	import java.security.MessageDigest;
18	import java.security.NoSuchAlgorithmException;
19	import java.util.HexFormat;
20	import java.util.function.Supplier;
21	
22	/**
23	 * 写操作幂等编排：
24	 * <ul>
25	 *   <li>权限校验由调用方在进入本服务前完成（权限先于幂等回放）；</li>
26	 *   <li>幂等参数包含操作者编号与角色，另加操作标识与参数指纹；</li>
27	 *   <li>同键同参重放原成功响应，异参返回 409；</li>
28	 *   <li>业务变更与幂等记录在同一事务原子提交，业务失败回滚，不占用幂等键；</li>
29	 *   <li>新键先插入占位行，利用主键约束串行化同键并发。</li>
30	 * </ul>
31	 */
32	@Service
33	public class IdempotencyService {
34	
35	    public static final String HEADER_REQUEST_ID = "X-Request-Id";
36	
37	    /** 同键并发占位冲突后的最大重试次数：等待胜出事务提交后回放，或其回滚后自行执行。 */
38	    private static final int MAX_ACQUIRE_ATTEMPTS = 10;
39	
40	    /** 一次写操作的业务结果：HTTP 状态码与响应体对象。 */
41	    public record WriteOutcome(int status, Object body) {
42	
43	        public static WriteOutcome of(int status, Object body) {
44	            return new WriteOutcome(status, body);
45	        }
46	    }
47	
48	    private final IdempotencyRepository repository;
49	    private final ObjectMapper objectMapper;
50	    /** 指纹专用 mapper：Map 条目按键排序，保证跨进程序列化结果确定。 */
51	    private final ObjectMapper fingerprintMapper;
52	    private final Clock clock;
53	
54	    public IdempotencyService(IdempotencyRepository repository, ObjectMapper objectMapper, Clock clock) {
55	        this.repository = repository;
56	        this.objectMapper = objectMapper;
57	        this.fingerprintMapper = objectMapper.copy()
58	                .configure(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS, true);
59	        this.clock = clock;
60	    }
61	
62	    /**
63	     * 计算请求参数指纹；操作标识、路径参数与请求体均参与。
64	     */
65	    public String fingerprint(String operation, Object params) {
66	        String json;
67	        try {
68	            json = fingerprintMapper.writeValueAsString(params);
69	        } catch (JsonProcessingException e) {
70	            throw ApiException.badRequest("请求参数无法序列化");
71	        }
72	        String raw = operation + "|" + json;
73	        try {
74	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
75	            return HexFormat.of().formatHex(digest.digest(raw.getBytes(StandardCharsets.UTF_8)));
76	        } catch (NoSuchAlgorithmException e) {
77	            throw new IllegalStateException("SHA-256 不可用", e);
78	        }
79	    }
80	
81	    /**
82	     * 在幂等保护下执行写操作；整个过程在一个事务内。
83	     */
84	    @Transactional
85	    public ResponseEntity<String> runWrite(String requestId, String operation, String fingerprint,
86	                                           Actor actor, Supplier<WriteOutcome> action) {
87	        for (int attempt = 0; attempt < MAX_ACQUIRE_ATTEMPTS; attempt++) {
88	            IdempotencyRepository.IdempotentRow existing = repository.lockByRequestId(requestId);
89	            if (existing != null) {
90	                return toReplay(existing, actor, operation, fingerprint);
91	            }
92	            boolean acquired;
93	            try {
94	                repository.insert(new IdempotencyRepository.IdempotentRow(
95	                        requestId, actor.actorId(), actor.role().name(), operation, fingerprint,
96	                        0, null, clock.nowMillis()));
97	                acquired = true;
98	            } catch (DuplicateKeyException e) {
99	                acquired = false;
100	            }
101	            if (acquired) {
102	                WriteOutcome outcome;
103	                try {
104	                    outcome = action.get();
105	                } catch (RuntimeException e) {
106	                    // 业务失败：事务回滚，占位行一并撤销，不占用幂等键。
107	                    throw e;
108	                }
109	                String bodyJson = toJson(outcome.body());
110	                repository.updateResult(requestId, outcome.status(), bodyJson);
111	                return jsonResponse(outcome.status(), bodyJson);
112	            }
113	            // 同键并发：等待胜出事务结束后回放；若对方回滚（行消失）则下一轮自行执行。
114	            IdempotencyRepository.IdempotentRow winner = repository.lockByRequestId(requestId);
115	            if (winner != null) {
116	                return toReplay(winner, actor, operation, fingerprint);
117	            }
118	        }
119	        throw ApiException.conflict("同 requestId 并发竞争激烈，请稍后重试");
120	    }
121	
122	    private ResponseEntity<String> toReplay(IdempotencyRepository.IdempotentRow row, Actor actor,
123	                                            String operation, String fingerprint) {
124	        if (!row.actorId().equals(actor.actorId())
125	                || !row.role().equals(actor.role().name())
126	                || !row.operation().equals(operation)
127	                || !row.fingerprint().equals(fingerprint)) {
128	            throw ApiException.conflict("requestId 已用于不同参数或操作者的请求");
129	        }
130	        return jsonResponse(row.responseStatus(), row.responseBody());
131	    }
132	
133	    private String toJson(Object body) {
134	        try {
135	            return objectMapper.writeValueAsString(body);
136	        } catch (JsonProcessingException e) {
137	            throw new IllegalStateException("响应体无法序列化", e);
138	        }
139	    }
140	
141	    private ResponseEntity<String> jsonResponse(int status, String bodyJson) {
142	        return ResponseEntity.status(status)
143	                .header(HttpHeaders.CONTENT_TYPE, MediaType.APPLICATION_JSON_VALUE)
144	                .body(bodyJson);
145	    }
146	}
