20	
21	/**
22	 * 受控揭盲：申请、批准、结果查询的主流程与失败分支；
23	 * 关闭/退组不撤销已批准揭盲；处理代码仅在批准后对申请人可见。
24	 */
25	@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
26	class UnblindFlowTest extends AbstractBlindIntegrationTest {
27	
28	    @Autowired
29	    private TestRestTemplate rest;
30	
31	    private final ObjectMapper mapper = new ObjectMapper();
32	
33	    private HttpHeaders headers(String actor, String role, String requestId) {
34	        HttpHeaders h = new HttpHeaders();
35	        h.set("X-Actor-Id", actor);
36	        h.set("X-Role", role);
37	        if (requestId != null) {
38	            h.set("X-Request-Id", requestId);
39	        }
40	        h.setContentType(MediaType.APPLICATION_JSON);
41	        return h;
42	    }
43	
44	    private ResponseEntity<String> exchange(String path, HttpMethod method,
45	                                            HttpHeaders headers, String body) {
46	        return rest.exchange(path, method, new HttpEntity<>(body, headers), String.class);
47	    }
48	
49	    private JsonNode json(ResponseEntity<String> response) throws Exception {
50	        assertNotNull(response.getBody());
51	        return mapper.readTree(response.getBody());
52	    }
53	
54	    private void setupExperimentWithParticipant(String expId, String requestIdPrefix) {
55	        assertEquals(201, exchange("/api/experiments/" + expId, HttpMethod.POST,
56	                headers("coord-1", "COORDINATOR", requestIdPrefix + "-create"),
57	                "{\"blockCount\":2}").getStatusCode().value());
58	        assertEquals(201, exchange(
59	                "/api/experiments/" + expId + "/participants/PA/allocations",
60	                HttpMethod.POST,
61	                headers("coord-1", "COORDINATOR", requestIdPrefix + "-alloc"), null)
62	                .getStatusCode().value());
63	    }
64	
65	    private String dbTreatment(long allocationId) {
66	        List<String> t = jdbc.queryForList(
67	                "SELECT s.treatment FROM allocation a JOIN seat s "
68	                        + "ON s.experiment_id = a.experiment_id "
69	                        + "AND s.block_no = a.block_no AND s.seat_no = a.seat_no "
70	                        + "WHERE a.id = ?", String.class, allocationId);
71	        return t.isEmpty() ? null : t.get(0);
72	    }
73	
74	    @Test
75	    void applyApproveAndResult_fullControlledUnblinding() throws Exception {
76	        setupExperimentWithParticipant("UB-1", "u1");
77	        long allocationId = jdbc.queryForObject(
78	                "SELECT id FROM allocation WHERE experiment_id = 'UB-1' AND participant_id = 'PA'",
79	                Long.class);
80	        String expectedTreatment = dbTreatment(allocationId);
81	        assertEquals("A", expectedTreatment, "第一区组第一席应为 A");
82	
83	        // 协调员申请揭盲
84	        ResponseEntity<String> apply = exchange(
85	                "/api/experiments/UB-1/participants/PA/unblind-requests", HttpMethod.POST,
86	                headers("coord-1", "COORDINATOR", "u1-apply"),
87	                "{\"reason\":\"合成测试需要核对处理代码\"}");
88	        assertEquals(201, apply.getStatusCode().value());
89	        JsonNode applyBody = json(apply);
90	        String ubId = applyBody.path("requestId").asText();
91	        assertEquals("PENDING", applyBody.path("status").asText());
92	        assertEquals("coord-1", applyBody.path("applicantActor").asText());
93	        assertFalse(applyBody.has("treatment"), "申请视图不得包含处理代码");
94	
95	        // 未批准：申请人查询结果 409
96	        ResponseEntity<String> pendingResult = exchange(
97	                "/api/unblind-requests/" + ubId + "/result", HttpMethod.GET,
98	                headers("coord-1", "COORDINATOR", null), null);
99	        assertEquals(409, pendingResult.getStatusCode().value());
100	
101	        // 协调员不能批准（仅 REVIEWER）
102	        ResponseEntity<String> coordinatorApprove = exchange(
103	                "/api/unblind-requests/" + ubId + "/approval", HttpMethod.POST,
104	                headers("coord-1", "COORDINATOR", "u1-approve-by-coord"), null);
105	        assertEquals(403, coordinatorApprove.getStatusCode().value());
106	
107	        // 申请人本人不能以 REVIEWER 身份批准（必须是另一名 REVIEWER）
108	        ResponseEntity<String> selfApprove = exchange(
109	                "/api/unblind-requests/" + ubId + "/approval", HttpMethod.POST,
110	                headers("coord-1", "REVIEWER", "u1-approve-self"), null);
111	        assertEquals(403, selfApprove.getStatusCode().value());
112	
113	        // 另一名 REVIEWER 批准
114	        clock.advance(10_000L);
115	        ResponseEntity<String> approved = exchange(
116	                "/api/unblind-requests/" + ubId + "/approval", HttpMethod.POST,
117	                headers("rev-2", "REVIEWER", "u1-approve"), null);
118	        assertEquals(200, approved.getStatusCode().value());
119	        JsonNode approvedBody = json(approved);
120	        assertEquals("APPROVED", approvedBody.path("status").asText());
121	        assertEquals("rev-2", approvedBody.path("reviewerActor").asText());
122	        assertFalse(approvedBody.has("treatment"), "批准响应仍不得直接返回处理代码");
123	
124	        // 重复批准 409
125	        ResponseEntity<String> twice = exchange(
126	                "/api/unblind-requests/" + ubId + "/approval", HttpMethod.POST,
127	                headers("rev-3", "REVIEWER", "u1-approve-twice"), null);
128	        assertEquals(409, twice.getStatusCode().value());
129	
130	        // 仅申请人可查结果
131	        ResponseEntity<String> result = exchange(
132	                "/api/unblind-requests/" + ubId + "/result", HttpMethod.GET,
133	                headers("coord-1", "COORDINATOR", null), null);
134	        assertEquals(200, result.getStatusCode().value());
135	        JsonNode resultBody = json(result);
136	        assertEquals(expectedTreatment, resultBody.path("treatment").asText());
137	        assertEquals("APPROVED", resultBody.path("status").asText());
138	        assertEquals(1_700_000_010_000L, resultBody.path("reviewedAt").asLong());
139	
140	        // 批准人及其他角色查结果：403
141	        assertEquals(403, exchange("/api/unblind-requests/" + ubId + "/result",
142	                HttpMethod.GET, headers("rev-2", "REVIEWER", null), null)
143	                .getStatusCode().value());
144	        assertEquals(403, exchange("/api/unblind-requests/" + ubId + "/result",
145	                HttpMethod.GET, headers("other-coord", "COORDINATOR", null), null)
146	                .getStatusCode().value());
147	
148	        // 申请状态查询：非申请人/非批准人 403
149	        assertEquals(403, exchange("/api/unblind-requests/" + ubId,
150	                HttpMethod.GET, headers("rev-3", "REVIEWER", null), null)
151	                .getStatusCode().value());
152	        assertEquals(200, exchange("/api/unblind-requests/" + ubId,
153	                HttpMethod.GET, headers("rev-2", "REVIEWER", null), null)
154	                .getStatusCode().value());
155	        assertEquals(404, exchange("/api/unblind-requests/UB-MISSING/result",
156	                HttpMethod.GET, headers("coord-1", "COORDINATOR", null), null)
157	                .getStatusCode().value());
158	    }
159	
160	    @Test
161	    void apply_requiresReason_andOnlyOnePendingPerAllocation() {
162	        setupExperimentWithParticipant("UB-2", "u2");
163	
164	        // REVIEWER 不能申请揭盲
165	        assertEquals(403, exchange(
166	                "/api/experiments/UB-2/participants/PA/unblind-requests", HttpMethod.POST,
167	                headers("rev-2", "REVIEWER", "u2-apply-by-reviewer"),
168	                "{\"reason\":\"x\"}").getStatusCode().value());
169	
170	        // 原因缺失
171	        assertEquals(400, exchange(
172	                "/api/experiments/UB-2/participants/PA/unblind-requests", HttpMethod.POST,
173	                headers("coord-1", "COORDINATOR", "u2-apply-blank"),
174	                "{\"reason\":\"\"}").getStatusCode().value());
175	
176	        // 正常申请
177	        ResponseEntity<String> first = exchange(
178	                "/api/experiments/UB-2/participants/PA/unblind-requests", HttpMethod.POST,
179	                headers("coord-1", "COORDINATOR", "u2-apply-1"),
180	                "{\"reason\":\"首次申请\"}");
181	        assertEquals(201, first.getStatusCode().value());
182	
183	        // 同一分配第二个待审申请 409
184	        ResponseEntity<String> second = exchange(
185	                "/api/experiments/UB-2/participants/PA/unblind-requests", HttpMethod.POST,
186	                headers("coord-1", "COORDINATOR", "u2-apply-2"),
187	                "{\"reason\":\"再次申请\"}");
188	        assertEquals(409, second.getStatusCode().value());
189	
190	        // 为不存在的参与者申请：404
191	        assertEquals(404, exchange(
192	                "/api/experiments/UB-2/participants/NOBODY/unblind-requests", HttpMethod.POST,
193	                headers("coord-1", "COORDINATOR", "u2-apply-missing"),
194	                "{\"reason\":\"x\"}").getStatusCode().value());
195	    }
196	
197	    @Test
198	    void approvedUnblinding_survivesWithdrawalAndClose() throws Exception {        setupExperimentWithParticipant("UB-3", "u3");
199	        ResponseEntity<String> apply = exchange(
200	                "/api/experiments/UB-3/participants/PA/unblind-requests", HttpMethod.POST,
201	                headers("coord-1", "COORDINATOR", "u3-apply"), "{\"reason\":\"核对\"}");
202	        String ubId = json(apply).path("requestId").asText();
203	        assertEquals(200, exchange("/api/unblind-requests/" + ubId + "/approval",
204	                HttpMethod.POST, headers("rev-2", "REVIEWER", "u3-approve"), null)
205	                .getStatusCode().value());
206	        String treatmentBefore = json(exchange("/api/unblind-requests/" + ubId + "/result",
207	                HttpMethod.GET, headers("coord-1", "COORDINATOR", null), null))
208	                .path("treatment").asText();
209	
210	        // 退组
211	        assertEquals(200, exchange(
212	                "/api/experiments/UB-3/participants/PA/withdrawal", HttpMethod.POST,
213	                headers("coord-1", "COORDINATOR", "u3-withdraw"), null)
214	                .getStatusCode().value());
215	        // 关闭实验
216	        assertEquals(200, exchange("/api/experiments/UB-3/close", HttpMethod.POST,
217	                headers("coord-1", "COORDINATOR", "u3-close"), null).getStatusCode().value());
218	
219	        // 已批准揭盲不撤销，申请人仍可查询到相同处理代码
220	        ResponseEntity<String> resultAfter = exchange(
221	                "/api/unblind-requests/" + ubId + "/result", HttpMethod.GET,
222	                headers("coord-1", "COORDINATOR", null), null);
223	        assertEquals(200, resultAfter.getStatusCode().value());
224	        assertEquals(treatmentBefore, json(resultAfter).path("treatment").asText());
225	        assertEquals("APPROVED", json(resultAfter).path("status").asText());
226	    }
227	
228	    @Test
229	    void unblindWrites_areIdempotent_replayReturnsOriginalResult() throws Exception {
230	        setupExperimentWithParticipant("UB-4", "u4");
231	
232	        // 申请揭盲：同键同参重放返回同一个申请，不产生第二条申请
233	        ResponseEntity<String> apply1 = exchange(
234	                "/api/experiments/UB-4/participants/PA/unblind-requests", HttpMethod.POST,
235	                headers("coord-1", "COORDINATOR", "u4-apply-key"),
236	                "{\"reason\":\"幂等申请\"}");
237	        assertEquals(201, apply1.getStatusCode().value());
238	        ResponseEntity<String> applyReplay = exchange(
239	                "/api/experiments/UB-4/participants/PA/unblind-requests", HttpMethod.POST,
240	                headers("coord-1", "COORDINATOR", "u4-apply-key"),
241	                "{\"reason\":\"幂等申请\"}");
242	        assertEquals(201, applyReplay.getStatusCode().value());
243	        assertEquals(apply1.getBody(), applyReplay.getBody());
244	        String ubId = json(apply1).path("requestId").asText();
245	        assertEquals(1, jdbc.queryForObject(
246	                "SELECT COUNT(*) FROM unblind_request WHERE allocation_id = "
247	                        + "(SELECT id FROM allocation WHERE experiment_id = 'UB-4' "
248	                        + "AND participant_id = 'PA')", Integer.class));
249	
250	        // 同键换原因：异参 409
251	        ResponseEntity<String> differentReason = exchange(
252	                "/api/experiments/UB-4/participants/PA/unblind-requests", HttpMethod.POST,
253	                headers("coord-1", "COORDINATOR", "u4-apply-key"),
254	                "{\"reason\":\"不同原因\"}");
255	        assertEquals(409, differentReason.getStatusCode().value());
256	
257	        // 批准：同键重放原成功结果（APPROVED），而非重复批准冲突
258	        ResponseEntity<String> approve1 = exchange(
259	                "/api/unblind-requests/" + ubId + "/approval", HttpMethod.POST,
260	                headers("rev-2", "REVIEWER", "u4-approve-key"), null);
261	        assertEquals(200, approve1.getStatusCode().value());
262	        ResponseEntity<String> approveReplay = exchange(
263	                "/api/unblind-requests/" + ubId + "/approval", HttpMethod.POST,
264	                headers("rev-2", "REVIEWER", "u4-approve-key"), null);
265	        assertEquals(200, approveReplay.getStatusCode().value());
266	        assertEquals(approve1.getBody(), approveReplay.getBody());
267	        assertEquals(1, jdbc.queryForObject(
268	                "SELECT COUNT(*) FROM unblind_request WHERE id = ? AND status = 'APPROVED' "
269	                        + "AND reviewer_actor = 'rev-2'", Integer.class, ubId));
270	    }
271	}
